lessons.exampleCode:
-- What does each critter like to eat?
SELECT name, snack
FROM critters;

solutionFiles.query.sql:
-- Mission: roll call at the Critter Club!

-- 1. Show every column of every critter.
SELECT * FROM critters;

-- 2. Show only the name and kind columns.
SELECT name, kind FROM critters;

starterFiles.query.sql:
-- 1. Only critters older than 3.
SELECT name FROM critters;

-- 2. Only the owls.
SELECT name, snack FROM critters;

-- 3. Only frogs younger than 3.
SELECT name FROM critters;

solutionFiles.query.sql:
-- 1. Only critters older than 3.
SELECT name FROM critters WHERE age > 3;

-- 2. Only the owls.
SELECT name, snack FROM critters WHERE kind = 'owl';

-- 3. Only frogs younger than 3.
SELECT name FROM critters
WHERE kind = 'frog' AND age < 3;

starterFiles.query.sql:
-- 1. Names from A to Z.
SELECT name FROM critters;

-- 2. Names and ages, oldest first.
SELECT name, age FROM critters;

-- 3. Just the 3 oldest critters.
SELECT name, age FROM critters;

solutionFiles.query.sql:
-- 1. Names from A to Z.
SELECT name FROM critters ORDER BY name;

-- 2. Names and ages, oldest first.
SELECT name, age FROM critters ORDER BY age DESC;

-- 3. Just the 3 oldest critters.
SELECT name, age FROM critters
ORDER BY age DESC LIMIT 3;

starterFiles.query.sql:
-- 1. How many critters are in the club?
SELECT name FROM critters;

-- 2. How many acorns altogether?
SELECT acorns FROM critters;

-- 3. How many critters of each kind?
SELECT kind FROM critters;

solutionFiles.query.sql:
-- 1. How many critters are in the club?
SELECT COUNT(*) FROM critters;

-- 2. How many acorns altogether?
SELECT SUM(acorns) FROM critters;

-- 3. How many critters of each kind?
SELECT kind, COUNT(*)
FROM critters
GROUP BY kind;

