solutionFiles.query.sql:
-- 1. Welcome Fern the deer (age 2, clover).
INSERT INTO critters (name, kind, age, snack)
VALUES ('Fern', 'deer', 2, 'clover');

-- 2. Pip's birthday: Pip is now 2.
UPDATE critters
SET age = 2
WHERE name = 'Pip';

-- 3. Pebble is moving away.
DELETE FROM critters
WHERE name = 'Pebble';

lessons.exampleCode:
-- A brand new table for snacks
CREATE TABLE snacks (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  crunchy INTEGER
);

INSERT INTO snacks (name, crunchy)
VALUES ('acorns', 1), ('berries', 0);

SELECT * FROM snacks;

CREATE TABLE reviews (
  id INTEGER PRIMARY KEY,
  game_title TEXT NOT NULL,
  stars INTEGER NOT NULL CHECK (stars BETWEEN 1 AND 5),
  comment TEXT NOT NULL DEFAULT ''
);

INSERT INTO reviews (game_title, stars)
VALUES ('Star Garden', 5), ('Byte Racers', 4);

SELECT * FROM reviews;
